<script setup lang="ts">
import{computed,ref}from'vue';import{t}from'../i18n';import NumberInput from'../components/NumberInput.vue';import{materialUsage}from'../logic/materialCalculators'
const measured=ref<number|null>(null),allowance=ref<number|null>(null),quantity=ref<number|null>(null),processMeters=ref<number|null>(null),formulaOpen=ref(false)
const result=computed(()=>materialUsage(measured.value??NaN,allowance.value??NaN,quantity.value??NaN,processMeters.value))
function reset(){measured.value=allowance.value=quantity.value=processMeters.value=null}
</script>
<template><div class="page business-page material-page"><header class="page-intro"><h1>{{t('materialUsage.title')}}</h1><p>{{t('materialUsage.intro')}}</p></header><div class="business-layout"><section class="panel input-panel"><h2><span>01</span>{{t('common.input')}}</h2><div class="fields-grid single-column"><NumberInput v-model="measured" :label="t('materialUsage.measured')" hint="" :unit="t('materialUsage.cm')"/><NumberInput v-model="allowance" :label="t('materialUsage.allowance')" :hint="t('materialUsage.allowanceHint')" :unit="t('materialUsage.cm')"/><NumberInput v-model="quantity" :label="t('materialUsage.orderQuantity')" hint="" :unit="t('materialUsage.pieces')"/><NumberInput v-model="processMeters" :label="t('materialUsage.processAmount')" :hint="t('materialUsage.optionalHint')" :unit="t('materialUsage.meters')" :optional="t('common.optional')"/></div></section><section class="panel business-result material-usage-result"><h2><span>02</span>{{t('common.result')}}</h2><template v-if="result"><div class="usage-conversion"><small>{{t('materialUsage.perPiece')}} {{result.perPieceCm.toFixed(2)}} {{t('materialUsage.cm')}}</small><small>{{t('materialUsage.totalCm')}} {{result.totalCm.toFixed(2)}} {{t('materialUsage.cm')}}</small><strong>{{result.totalMeters.toFixed(2)}} <i>{{t('materialUsage.meters')}}</i></strong></div><div v-if="result.difference!==null" class="usage-status" :class="result.difference<0?'negative':'positive'"><small>{{t('materialUsage.difference')}}</small><b>{{result.difference>0?'+':''}}{{result.difference.toFixed(2)}} {{t('materialUsage.meters')}}</b><em>{{result.difference<0?t('materialUsage.insufficient'):t('materialUsage.sufficient')}}</em></div></template><p v-else class="business-waiting">{{t('common.waiting')}}</p><button class="business-reset" @click="reset">{{t('common.reset')}}</button></section></div><details class="business-support" :open="formulaOpen" @toggle="formulaOpen=($event.target as HTMLDetailsElement).open"><summary>{{t('common.formula')}}</summary><div><code>{{t('materialUsage.formula1')}}</code><code>{{t('materialUsage.formula2')}}</code><code>{{t('materialUsage.formula3')}}</code><code>{{t('materialUsage.formula4')}}</code></div></details></div></template>
